# -*- coding: utf-8 -*-
"""Recomendaciones de práctica/ejercitación y próximos pasos por concepto PA V6 (complementan ensayos_pa_*.py)."""
P = {
"G1.1-PA01": (["Redactar la ficha de rol PO-GAC con matriz de derechos de decisión en tres niveles (PO-GAC / dueño del riesgo / CISO) para el control de correo y colaboración.","Comparar esa ficha con la descripción actual del puesto de analista y con los arquetipos de CISO (G1.1-K03): listar las cinco decisiones que hoy nadie tiene asignadas.","Simular con el manager una negociación de autoridad: qué se concede, qué se condiciona y qué evidencia se exige a cambio."],["Llevar la ficha al CISO para aprobación; registrar la decisión y la fecha.","Usar la ficha como insumo de M1.1-PA01 (organigrama híbrido y RACI) y de M1.2-PA03 (itinerario).","Verificar en el tenant que los permisos de Unified RBAC coinciden con los derechos de decisión declarados."]),
"G1.2-PA01": (["Construir el modelo de costo por tarea de AG-10, AG-03 y AG-05 (unidad de consumo × frecuencia + parte fija prorrateada) y compararlo con la alternativa humana y con un MDR.","Correr dos escenarios de sensibilidad: consumo ×2 y tasa de aceptación de propuestas al 70 %; documentar qué agente deja de justificarse.","Redactar el caso de negocio en una página con tabla de supuestos y fuente por cifra."],["Validar las tarifas de SCU, capacidad de Copilot Studio y modelos de Foundry en el tenant antes de presentar.","Trasladar el modelo a M1.2-PA01 (presupuesto, alertas) y al KPI-18 (horas liberadas medidas).","Registrar el 'costo descontrolado' como riesgo en G4.1-PA02."]),
"G2.1-PA01": (["Completar la grilla función/categoría CSF 2.0 × pilar Zero Trust para el control de correo y colaboración, marcando dominio principal y secundarios.","Extender la grilla a los siete pilares de una organización tipo y detectar celdas sin dueño y celdas con dos dueños; proponer el criterio de arbitraje.","Definir tres productos-control (p. ej., correo y colaboración, identidades, endpoints) con owner, tecnología y modelo operativo."],["Validar la grilla con el CISO y los owners actuales; registrar los solapamientos aceptados.","Usar la grilla como insumo de M1.1-PA02 (portafolio) y de la ficha de producto-control (C1.1).","Revisar la grilla cuando cambie la tecnología o el alcance del dominio."]),
"G2.1-PA02": (["Mapear los 24 AGC a las funciones y categorías del AI RMF y a los controles del Anexo A de ISO/IEC 42001, marcando cada correspondencia como fuerte, parcial o informativa.","Para AG-02 (remediación), listar la evidencia del tenant que respaldaría cada función del AI RMF y señalar la que hoy no existe.","Identificar qué registros del SGSI ya cubren controles de agentes para no duplicar comités ni repositorios."],["Cargar la matriz en Purview Compliance Manager si existe plantilla aplicable; si no, en el GRC.","Usar la matriz como base de G2.2-PA01 (política) y M3.2-PA02 (catálogo AGC).","Revisar la matriz cuando cambien las versiones de AI RMF/ISO 42001 o el perfil agéntico de CSA."]),
"G2.2-PA01": (["Redactar la política de agentes (3 páginas) con alcance, autoridades, prohibiciones, autonomía permitida por tipo de acción, identidad, datos, evidencia y revisión.","Construir la matriz regla → control técnico (DLP y conectores de Power Platform, compartición, plantillas de Agent 365, Conditional Access) → evidencia; marcar al menos una regla que solo un humano puede hacer cumplir.","Contrastar la política con la configuración por defecto del entorno de desarrollo de Copilot Studio y listar las reglas que hoy se violarían."],["Aprobar la política con el CISO y la segunda línea; publicar la versión y la fecha de revisión.","Derivar el estándar de ficha (G2.2-PA02) y los controles AGC-01 a AGC-04.","Revisar la matriz de aplicación tras cada cambio relevante de la plataforma (AG-09)."]),
"G2.2-PA02": (["Completar la ficha de AG-10, AG-03 y AG-05 con los anexos de agente del sub-plan (tools, knowledge, skills propios y comunes).","Mapear cada campo de la ficha a su ubicación en la plataforma (Copilot Studio, Power Platform admin center, Entra Agent ID, Agent 365).","Escribir el runbook de pausa y retiro de AG-03 y ejecutarlo en el entorno de desarrollo."],["Versionar la ficha junto con el agente en el ALM (M6.2-PA02).","Usar la ficha como pieza 1 del expediente ATO (AMP-22).","Revisar la coherencia entre autonomía declarada y permisos efectivos en cada cambio (M2.2-PA01)."]),
"G2.2-PA03": (["Diseñar el procedimiento de excepciones del control de correo (solicitud, evaluación, aprobador por impacto, caducidad, registro, revisión mensual).","Clasificar diez excepciones (reales o simuladas) de Tenant Allow/Block List y overrides por riesgo; proponer cuáles vencen y cuándo.","Ejecutar Configuration Analyzer frente a Standard/Strict y documentar cada desviación como error o excepción con dueño."],["Incorporar la revisión de overrides a la cadencia mensual (MDO-M02) y definir el KPI-07.","Conectar el procedimiento con el control continuo de deriva (G3.2-PA01) y con AG-10/AG-11.","Proponer la caducidad por defecto como regla de la política de agentes y del control."]),
"G3.1-PA01": (["Clasificar los 15 agentes del catálogo por exposición regulatoria (datos personales que tocan, decisiones sobre personas, jurisdicción) con justificación.","Para los tres de mayor exposición, listar obligaciones aplicables y la evidencia del tenant que las satisface (Purview Audit, retención, disclosure).","Preparar las preguntas para Legal y Privacidad sobre los casos dudosos."],["Incorporar la clasificación regulatoria como pieza 9 del expediente ATO (AMP-22).","Revisar la clasificación ante cambios regulatorios o de alcance de los agentes.","Conectar con AGC-11 (trazabilidad) y AGC-21 (transparencia)."]),
"G3.2-PA01": (["Diseñar el control continuo de deriva: fuente (Configuration Analyzer/ORCA/Secure Score), frecuencia, umbral, dueño, acción y evidencia.","Escribir una detección personalizada (KQL) sobre cambios de política de correo y probarla con un cambio controlado en el entorno de prueba.","Producir el primer informe de deriva con remediación y excepciones registradas."],["Asignar AG-10 como centinela (L3 detección / L2 corrección) y definir el KPI-06.","Enlazar cada desviación aceptada con el registro de excepciones (G2.2-PA03).","Mapear el control continuo a ISO 27001/42001 (HC-005) y a la evidencia continua (AMP-13)."]),
"G4.1-PA01": (["Asignar las tres líneas para la flota del control: qué revisa cada una, con qué evidencia y con qué frecuencia.","Construir el RACI de las 16 actividades de gobierno y gestión de agentes; verificar una sola A por actividad.","Simular un desacuerdo entre owner y segunda línea sobre el nivel de autonomía de AG-02 y documentar la ruta de escalamiento."],["Acordar con auditoría interna el acceso a trazas y expedientes sin depender del owner (AGC-22).","Configurar en Agent 365 las reglas de segunda línea (agentes sin dueño, inactivos).","Revisar el RACI al incorporar agentes de proveedores (M1.2-PA02)."]),
"G4.1-PA02": (["Traducir los diez ASI del OWASP Agentic Top 10 al lenguaje del registro de riesgos corporativo (escenario, causa, consecuencia) para la flota.","Poblar el registro con diez riesgos: agente afectado, control AGC, KRI, dueño y tratamiento; evitar el doble conteo con el riesgo del control.","Conectar tres de esos riesgos a señales reales (Defender para IA, Purview, Agent 365)."],["Definir los KRIs de la flota (G4.2-PA01) a partir de los riesgos registrados.","Cruzar el registro con la matriz amenaza→agente→control (M4.2-PA02).","Revisar la taxonomía cuando OWASP publique una nueva versión."]),
"G4.2-PA01": (["Definir ocho KRIs de la flota (al menos uno de costo, calidad, identidad y comportamiento) con fuente, umbral, acción y dueño.","Derivar cada umbral del apetito de autonomía declarado (AMP-17) y de datos históricos del entorno de prueba.","Construir una consulta en Sentinel o Agent 365 que materialice dos de los KRIs."],["Integrar los KRIs al tablero de la flota (M4.1-PA05) y al monitoreo AGC-14.","Revisar umbrales tras la primera revisión de desempeño (M4.1-PA06).","Contrastar los KRIs con los 20 KPIs del sub-plan usando HC-027."]),
"G6.1-PA01": (["Preparar el reporte trimestral de dos páginas con la plantilla (valor, costo, riesgo, incidentes, flota, decisiones) a partir de datos del entorno de prueba.","Redactar el caso difícil: un trimestre con más tareas ejecutadas por agentes y un error relevante; separar hechos, inferencias y rangos.","Presentarlo a un par que haga de CISO y registrar qué decisión tomaría y con qué dato."],["Automatizar el anexo de datos desde Power BI/Sentinel.","Usar el reporte como entregable del capstone (E5).","Incorporar el protocolo de comunicación de incidentes de agentes (HC-020)."]),
"G6.2-PA01": (["Definir seis métricas de gobierno de la flota con fuente, meta y denominador declarado; al menos una de resultado.","Estimar el denominador real de agentes en el tenant (Power Platform admin center, Agent 365, inventario de app registrations) y compararlo con el registro.","Producir el primer corte y comentar qué métrica podría 'premiar no registrar'."],["Publicar las métricas en el tablero de gobierno (AGC-24) y en el reporte trimestral (G6.1-PA01).","Definir la regla de detección de agentes no registrados (M6.2-K06).","Revisar las métricas con la segunda línea tras el primer trimestre."]),
"M1.1-PA01": (["Dibujar el organigrama híbrido del control (6 personas, 15 agentes, 1 MDR) con relaciones de reporte y sponsors.","Calcular el span of control de cada owner a partir del tiempo de revisión de muestras y aprobaciones L2 por agente; marcar el límite.","Completar el RACI de las 16 actividades de gobierno y gestión de agentes e incluir la interfaz con el MDR."],["Registrar sponsors en Entra Agent ID y la relación owner–agente en Agent 365.","Usar el organigrama en M1.2-PA03 (itinerario) y como evidencia de AGC-02/AGC-23.","Revisar el span of control si se duplica la flota o cambia la ruta de construcción."]),
"M1.1-PA02": (["Definir cinco productos-control con owner, tecnología, modelo operativo, métricas, backlog y presupuesto de agentes.","Simular una revisión de portafolio: comparar cobertura, deuda y riesgo residual (no un número único) y decidir dónde reasignar agentes.","Agrupar los productos por pilar Zero Trust y justificar los owners con varios productos."],["Alinear el portafolio con la grilla de ownership (G2.1-PA01).","Derivar el presupuesto por producto (M1.2-PA01).","Revisar el portafolio trimestralmente junto con el reporte ejecutivo (G6.1-PA01)."]),
"M1.1-PA03": (["Derivar diez prácticas eo:OP (verbo + objeto + cadencia + rol + evidencia) de las 31 tareas del modelo operativo MDO/XDR.","Redactar la política de modelo operativo del programa: qué debe tener todo producto-control y cómo se mide la excelencia operacional.","Auditar seis meses hacia atrás: qué tareas de mantenimiento del control no se hicieron y qué métrica debería haberlo mostrado."],["Proponer las eo:OP nuevas al MAEO mediante ChangeSet.","Aplicar la política de modelo operativo al portafolio (M1.1-PA02).","Vincular con M4.1-PA01 (modelo operativo concreto)."]),
"M1.2-PA01": (["Construir el modelo de costos de la flota (SCU, capacidad de Copilot Studio, tokens de Foundry, licencias) con costo por tarea por agente.","Definir presupuesto trimestral con reserva para picos, alertas en Azure Cost Management y regla de atribución en cadenas AG-01→AG-02.","Proponer tres optimizaciones (modelo, prompt, frecuencia) y estimar su efecto."],["Operar el ritual mensual de revisión de consumo (KPI-14/15) y el AGC-15.","Alimentar el reporte ejecutivo (G6.1-PA01) con costo por tarea.","Revisar la decisión de ruta de construcción (M6.2-PA01) con los datos de consumo reales."]),
"M1.2-PA02": (["Redactar el anexo de requisitos de IA y agentes para un RFP de MDR (identidad, permisos, datos, evidencia, autonomía, kill switch, incidentes, métricas, salida).","Construir la matriz de evaluación de propuestas con criterio verificable por requisito.","Revisar un contrato vigente (o plantilla) y marcar qué cláusula se aplicaría ante un error del agente del proveedor."],["Alinear el anexo con la política de agentes (G2.2-PA01) y el RACI (G4.1-PA01).","Incorporar los agentes del proveedor al registro (M2.1-PA01) y al organigrama híbrido (M1.1-PA01).","Revisar el anexo con Legal y Compras."]),
"M1.2-PA03": (["Completar la autoevaluación de las 41 competencias (N1–N4) con una evidencia real por competencia acreditada.","Construir el plan individual E0–E5 con hitos, evidencias y horas protegidas; acordarlo con el manager.","Seleccionar módulos de apoyo (Ninja Training, Microsoft Learn) y validar vigencia de certificaciones (SC-200, SC-401, AI-900, AAISM)."],["Registrar la autoevaluación como línea base y repetirla al cierre de E3 y E5.","Usar el itinerario como evidencia del AGC-23 antes de operar agentes L2+.","Revisar el itinerario con los resultados de la revisión de desempeño de la flota."]),
"M2.1-PA01": (["Inventariar los 15 agentes del catálogo con dueño, sponsor, criticidad, datos, dependencias (modelo, conectores, knowledge, identidad), autonomía, estado y fecha de revisión.","Definir el criterio de inclusión (por lo que el agente puede tocar) y aplicarlo a agentes del MDR, nativos y personales.","Diseñar la regla de descubrimiento de agentes no registrados (Power Platform admin center, Agent 365, app registrations)."],["Cargar el inventario en Agent 365 y conectarlo con AGC-01/AGC-19.","Alimentar el mapa de dependencias de M6.1-PA01.","Reconciliar el inventario mensualmente contra lo observado en el tenant."]),
"M2.2-PA01": (["Construir la matriz tarea→rol humano→permisos del agente para las 31 tareas (Unified RBAC, roles de Exchange/MDO, conectores, API permissions).","Revisar los permisos de conectores de AG-02, AG-03 y AG-10 contra sus fichas y anexos; documentar excesos y compensaciones.","Configurar acceso condicional para una identidad de agente en el entorno de prueba y verificar el efecto."],["Usar la matriz como evidencia de AGC-05/06 y como insumo de la recertificación trimestral (AGC-18, MDO-Q03).","Actualizar la matriz en cada cambio de ficha o de conector (M6.2-PA02).","Reportar permisos excesivos no compensables como riesgo (G4.1-PA02)."]),
"M3.1-PA01": (["Dibujar la arquitectura objetivo del SOC agéntico con las seis capas y los límites de confianza; marcar disponibilidad (GA/preview/pendiente) de cada integración.","Trazar el camino de un correo hostil desde la señal hasta una acción de agente y señalar la capa que impide que se convierta en instrucción.","Verificar la coherencia del diagrama con los anexos de los 15 agentes (tools, knowledge, identidad)."],["Usar el diagrama como base de M6.2-PA01 (rutas) y del documento 07.","Actualizarlo tras cambios de plataforma detectados por AG-09.","Someterlo a revisión de arquitectura y de la segunda línea."]),
"M3.1-PA02": (["Dibujar el flujo de protección del correo (autenticación, filtrado, anti-phishing, detonación, URL, remediación post-entrega) y ubicar en él las tareas MDO-D05–D09 y M01–M03.","Analizar cinco casos de entrega (bloqueado en autenticación, detonado, reescrito, entregado y removido por ZAP, entregado por override) y señalar la capa que decidió.","Explicar en cinco minutos a un no especialista por qué un phishing reciente llegó a un buzón."],["Usar el diagrama como base técnica de M4.1-PA01–PA04 y M4.2-PA01.","Verificar en el tenant la configuración de cada capa frente a Standard/Strict (G2.2-PA03).","Extender el análisis a Teams, SharePoint y OneDrive; instanciar en los demás dominios (paquetes Dominio_*)."]),
"M3.2-PA01": (["Documentar la cadena objetivo → configuración → evidencia → KPI → owner para cinco controles de Defender for Office 365.","Buscar un caso en el que la configuración cumple y el objetivo no (p. ej., un override que permite lo que el objetivo prohíbe) y documentarlo.","Redactar la ficha de producto-control del dominio usando las cinco cadenas."],["Incorporar las cadenas al tablero de KPIs del control (C1.4).","Conectar con el control continuo de deriva (G3.2-PA01).","Revisar la cadena cuando cambie una política o el baseline."]),
"M3.2-PA02": (["Evaluar los 15 agentes contra los 24 AGC (implementado / parcial / no aplica / pendiente) con evidencia del tenant.","Aplicar un criterio de selección proporcional por nivel de autonomía y datos que toca; justificar los 'no aplica'.","Construir el plan de cierre y decidir qué agente debería pausarse hasta cumplir."],["Mapear los AGC a AI RMF, ISO 42001 y CSA AICM (G2.1-PA02) y a la matriz de estándares del programa.","Usar la evaluación como pieza del expediente ATO (AMP-22).","Revisar el catálogo cuando cambien OWASP/AICM."]),
"M3.2-PA03": (["Construir un dataset dorado de 50 incidentes clasificados para AG-01 (prioridad, clasificación, siguiente acción) con doble etiquetado.","Ejecutar la evaluación en Foundry o con pruebas de Copilot Studio midiendo distribuciones (varias corridas); fijar y defender el criterio de aceptación.","Diseñar el mecanismo para alimentar el dataset con los casos clasificados del runbook (MDO-D04)."],["Repetir la evaluación en cada versión (AGC-12/16) y registrar la línea base para M4.1-PA06.","Combinar con la evaluación adversarial (AMP-37) en el expediente ATO.","Extender el método a AG-03 y AG-10."]),
"M4.1-PA01": (["Operar el runbook de 31 tareas durante dos semanas en el entorno de prueba, registrando evidencia por tarea (capturas, decisiones, entradas con vencimiento, acciones del Action center).","Medir el cumplimiento de cadencias y el tiempo por tarea; identificar cuellos de botella.","Clasificar cada tarea por nivel de autonomía candidato (L0–L3) y asignar agente; justificar AG-10, AG-03 y AG-05 como primeros."],["Formalizar el runbook como documento 04 con KPIs por tarea y persona responsable.","Usar los tiempos medidos como línea base del KPI-18 (horas liberadas).","Derivar las prácticas eo:OP (M1.1-PA03); instanciar en XDR, Endpoints, Identidades, Datos, SIEM y Nube."]),
"M4.1-PA02": (["Triar 20 incidentes de laboratorio aplicando el orden de prioridad de la guía; registrar prioridad, acciones, clasificación, tipo de amenaza y tiempo.","Hacer que dos personas triajen los mismos 10 incidentes y medir el desacuerdo; derivar criterios de clasificación para la instrucción de AG-01.","Escalar dos incidentes a ITSM y verificar la trazabilidad (AG-15)."],["Alimentar el dataset dorado de AG-01 (M3.2-PA03) con los incidentes clasificados.","Medir KPI-01 y KPI-02 sobre la bitácora.","Construir los playbooks híbridos (M5.1-PA01) sobre los casos reales."]),
"M4.1-PA03": (["Analizar diez casos FP/FN (Submissions, TABL, cuarentena, reportes de usuarios) con causa raíz (motor / configuración / override / lista), acción y vencimiento.","Calcular precision y recall del período con los datos del entorno de prueba y discutir qué esconde cada cifra (HC-027).","Redactar la regla de 'allow con segunda aprobación' e incorporarla a la ficha de AG-03."],["Operar KPI-04 y KPI-05 semanalmente.","Conectar los casos recurrentes con el procedimiento de excepciones (G2.2-PA03).","Construir el dataset de casos FP/FN para evaluar a AG-03; instanciar en XDR, MDE, MDI y Purview."]),
"M4.1-PA04": (["Escribir cinco consultas KQL de hunting sobre tablas de correo y URL (p. ej., clics en URL reescritas desde cuentas prioritarias, patrones de envío sospechosos) con hipótesis documentada.","Convertir dos hallazgos en reglas de detección personalizadas con dueño, prueba y versión.","Publicar las consultas como compartidas en un repositorio Git/SharePoint que sirva de knowledge source a AG-14."],["Definir el proceso de curaduría y versionado de consultas (C3.4).","Medir precisión de las detecciones creadas y retirarlas si son ruidosas.","Explorar el servidor MCP de Sentinel como herramienta de AG-14 (ruta R3)."]),
"M4.1-PA05": (["Definir el esquema de registro (siempre / por muestreo / nunca) para los 15 agentes y su ruta de construcción.","Construir el tablero de la flota (Foundry tracing o App Insights, Agent 365, logs de Copilot Studio, Sentinel) con tres alertas de comportamiento (herramienta fuera de allowlist, consumo por tarea > umbral, precisión < umbral).","Probar una alerta de punta a punta hasta la cola de incidentes y verificar quién la ve."],["Medir KPI-20 (cobertura de observabilidad) y cerrar brechas.","Integrar los KRIs (G4.2-PA01) al tablero.","Documentar los requisitos de telemetría forense (AMP-45) por agente."]),
"M4.1-PA06": (["Conducir la revisión trimestral de AG-03 con la plantilla (resultados vs. metas, incidentes, costo, riesgo, cambios, decisión) sobre datos del entorno de prueba.","Muestrear 30 decisiones del agente y compararlas con la línea base del dataset dorado; estimar la deriva.","Redactar la decisión (mantener / ajustar / cambiar autonomía / pausar / retirar) y quién la firma."],["Programar MDO-Q02 para toda la flota y conectar con AGC-14.","Convertir los hallazgos en ChangeSets (M5.2-PA02).","Refrescar el dataset dorado con los casos del trimestre (M3.2-PA03)."]),
"M4.2-PA01": (["Analizar tres campañas (Campaign Views, Threat analytics): técnica ATT&CK, infraestructura, capa que detuvo cada mensaje, mensajes entregados.","Diseñar una simulación en Attack Simulation Training alineada a la campaña más relevante y definir su métrica.","Delimitar para el BEC qué es control técnico y qué es proceso de negocio; proponer la interfaz."],["Alimentar las instrucciones de AG-04 y AG-06 con los patrones observados.","Conectar con la concientización (MDO-M04, AG-12).","Revisar las campañas contra la matriz amenaza→agente (M4.2-PA02); instanciar en los demás dominios."]),
"M4.2-PA02": (["Cruzar los 10 ASI (OWASP Agentic Top 10 v2.01) con los 15 agentes: exposición, causa (lee correo hostil, invoca remediación, consulta fuentes externas), control AGC y mitigación Microsoft.","Diseñar una prueba de inyección indirecta sobre AG-01/AG-02 con un correo que intente ordenar una remediación; ejecutarla en el entorno de prueba.","Mapear las mismas amenazas a MITRE ATLAS y a CSA MAESTRO para verificar que no quedan clases sin cubrir."],["Trasladar los hallazgos al registro de riesgos (G4.1-PA02) y a AGC-08.","Incluir las pruebas en el expediente ATO (AMP-37).","Actualizar la matriz en cada nueva versión de OWASP/ATLAS."]),
"M5.1-PA01": (["Redactar el playbook híbrido de phishing de credenciales con clic: pasos, ejecutor (humano / AIR / AG-01 / AG-02), nivel, aprobación, herramienta, evidencia.","Redactar el playbook de BEC sin enlace cruzando la frontera con el proceso de negocio (verificación de pagos).","Revisar ambos con el SOC Lead y marcar los pasos 'nunca delegar'."],["Ejecutar los playbooks en laboratorio (M5.2-PA01).","Usarlos como guion del tabletop con agentes (AMP-43).","Versionarlos junto con las fichas de los agentes implicados."]),
"M5.2-PA01": (["Ejecutar la respuesta a tres incidentes de laboratorio: AIR, acciones manuales en Threat Explorer y acciones propuestas por AG-02 aprobadas en L2 con límite de lote.","Probar la reversión de una eliminación suave y documentar el tiempo y la evidencia.","Fijar el límite de lote por tipo de acción y justificarlo con el apetito de autonomía."],["Medir KPI-12 (acciones revertidas) sobre la bitácora.","Incorporar los límites a la ficha y a los permisos de AG-02 (M2.2-PA01).","Alimentar el post-mortem (M5.2-PA02) con los errores observados."]),
"M5.2-PA02": (["Simular un fallo de AG-03 (liberó de cuarentena un mensaje malicioso por instrucción ambigua) y reconstruir la traza completa (qué vio, qué decidió, con qué autoridad).","Proponer el ChangeSet (instrucción, conocimiento, herramienta o umbral) y ejecutar la regresión contra el dataset dorado.","Registrar aprobación y nueva versión en el ALM de Power Platform."],["Formalizar el pipeline de cambios (M6.2-PA02) y el AGC-16.","Alimentar la política y los procedimientos con la lección (HC-035).","Repetir el ejercicio con un fallo de AG-02 (remediación)."]),
"M6.1-PA01": (["Mapear las dependencias de los 15 agentes (plataforma, modelo, conectores/MCP, knowledge, identidad) a partir de los anexos.","Ejecutar un día del runbook en modo manual (sin agentes) midiendo tiempo por tarea y tareas no realizadas; priorizar explícitamente.","Redactar los disparadores del modo degradado y el plan de recuperación de la flota."],["Programar el ejercicio en modo manual al menos semestralmente.","Registrar la concentración tecnológica como riesgo estratégico (HC-023, AMP-15).","Incluir la recuperación de agentes en el BCDR del programa."]),
"M6.2-PA01": (["Completar la matriz de responsabilidad compartida (plataforma / owner / segunda línea) para R1, R2 y R3 con los anexos de agentes como insumo.","Elegir y justificar la ruta para cinco agentes (AG-01, AG-02, AG-10, AG-14, AG-15) por autonomía, datos, costo y capacidad del equipo.","Verificar en el tenant la disponibilidad (GA/preview) de Sentinel MCP, Microsoft MCP Server for Enterprise y Agent ID para los agentes elegidos."],["Trasladar el costo por ruta al modelo FinOps (M1.2-PA01).","Documentar la postura de IA en nube de los recursos de Foundry (AMP-51).","Revisar la decisión de ruta en cada revisión de desempeño."]),
"M6.2-PA02": (["Diseñar el pipeline de AG-03: entornos dev/test/prod de Power Platform, solución, repositorio Git de instrucciones y conocimiento, evaluación automatizada, aprobación, despliegue con versión.","Ejecutar un ciclo completo cambio → regresión → aprobación → despliegue → reversión en el entorno de prueba.","Definir la graduación de pruebas por tipo de cambio (umbral / instrucción / herramienta)."],["Aplicar el pipeline a los agentes comunes (tools y knowledge compartidos) con control de impacto cruzado.","Vincular con AGC-16 y el post-mortem (M5.2-PA02).","Evaluar pipelines de Power Platform o GitHub Actions para automatizar."]),
"M6.2-PA03": (["Construir la tabla agnóstico ↔ Microsoft para 15 capacidades con grado de portabilidad (alto / medio / bajo) justificado.","Tomar los anexos de dos agentes y separar lo portable (ficha, controles AGC, prácticas eo:OP, MCP) de lo dependiente (conectores propietarios, identidad de plataforma).","Redactar la cláusula de portabilidad que debería tener cualquier contrato de plataforma de agentes (M1.2-PA02)."],["Mantener la tabla como anexo vivo del sub-plan.","Preferir MCP y OpenAPI sobre conectores propietarios cuando la portabilidad sea un criterio.","Reevaluar la madurez de MCP/A2A cada semestre."]),
}
